// Izvuci AI tekst iz Responses API formata
const aiContent = $json.output?.[0]?.content?.[0]?.text || '';

// Lead podaci dolaze iz 'Take 1 Lead' nodea (pre OpenAI)
const lead = $('Take 1 Lead').item.json;

let parsed;
try {
  const cleaned = aiContent.replace(/^```json\n?|^```\n?|\n?```$/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    subject: `pitanje za ${lead['Naziv firme'] || 'vašu firmu'}`,
    body: aiContent
  };
}

return {
  row_number:    lead.row_number,
  email:         lead['Email'] || '',
  company:       lead['Naziv firme'] || '',
  category:      lead['Kategorija'] || '',
  city:          lead['Grad'] || '',
  phone:         lead['Telefon'] || '',
  email_subject: parsed.subject,
  email_body:    parsed.body
};

// AI telo + potpis = finalni plain text email
const body = ($json.email_body || '').trim();

const signature = [
  'Srdačan pozdrav,',
  'Matija Radulović',
  'Horizen AI · horizen.rs'
].join('\n');

const ps = 'P.S. Ako vam ovo nije relevantno, samo odgovorite "ne" i neću vas više pisati.';

return { ...$json, email_body_text: `${body}\n\n${signature}\n\n${ps}` };

const d = $('Parse Response').item.json;

const log = {
  timestamp: new Date().toISOString(),
  email:   d.email,
  company: d.company,
  subject: d.email_subject,
  status:  'draft_created'
};
console.log('DRAFT CREATED:', JSON.stringify(log));
return { success: true, ...log };
